import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Sidebar from './Sidebar';
import logo from '../logo.png';

// Modular Student Sub-Components
import StudentMaterials from './StudentMaterials';
import StudentActivities from './StudentActivities';
import StudentExams from './StudentExams';
import StudentTimetable from './StudentTimetable';
import Studentfeedback from './Studentfeedback';
import StudentProfileSettings from './StudentProfileSettings';

export default function StudentDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('Overview');
  const [selectedSubject, setSelectedSubject] = useState('');
  
  const [timetable, setTimetable] = useState([]);
  const [materialsCount, setMaterialsCount] = useState(0);
  const [quizzesCount, setQuizzesCount] = useState(0);

  // 🟢 SMART NAME RESOLVER (Any key, prop or LocalStorage)
  const getStudentRealName = () => {
    // Check direct props
    if (user?.name) return user.name;
    if (user?.full_name) return user.full_name;
    if (user?.student_name) return user.student_name;
    if (user?.username) return user.username;
    if (user?.email) return user.email.split('@')[0];

    // Check LocalStorage Session
    try {
      const savedUser = JSON.parse(localStorage.getItem('user') || '{}');
      if (savedUser.name) return savedUser.name;
      if (savedUser.full_name) return savedUser.full_name;
      if (savedUser.student_name) return savedUser.student_name;
      if (savedUser.username) return savedUser.username;
      if (savedUser.email) return savedUser.email.split('@')[0];
    } catch (e) {
      console.error(e);
    }
    return "Student";
  };

  const [studentName, setStudentName] = useState(getStudentRealName());
  const studentGrade = user?.grade || JSON.parse(localStorage.getItem('user') || '{}')?.grade || "Grade 8";
  
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : String(user.subjects).split(',').map(s => s.trim()).filter(Boolean)) 
    : ["Mathematics", "Science", "English"];

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  useEffect(() => {
    // 🟢 Dynamic Name Sync
    const currentName = getStudentRealName();
    if (currentName !== 'Student') {
      setStudentName(currentName);
    }

    const studentId = user?.id || JSON.parse(localStorage.getItem('user') || '{}')?.id;

    // Fetch Student Name from DB if available
    if (studentId) {
      axios.get(`http://localhost:8082/api/students/${studentId}`)
        .then(res => {
          if (res.data) {
            const dbName = res.data.name || res.data.full_name || res.data.student_name;
            if (dbName) setStudentName(dbName);
          }
        }).catch(() => {});
    }

    const targetGradeNum = studentGrade.replace(/\D/g, '');

    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        const data = res.data || [];
        const filtered = data.filter(t => (t.grade || '').replace(/\D/g, '') === targetGradeNum);
        setTimetable(filtered.length > 0 ? filtered : data);
      }).catch(() => setTimetable([]));

    axios.get('http://localhost:8082/api/learning-materials').then(res => setMaterialsCount((res.data || []).length)).catch(() => setMaterialsCount(0));
    axios.get('http://localhost:8082/api/quizzes').then(res => setQuizzesCount((res.data || []).length)).catch(() => setQuizzesCount(0));
  }, [studentGrade, user]);

  const handleSubjectClick = (sub) => {
    setSelectedSubject(sub);
    setActiveTab('Study Materials');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'Overview':
        return (
          <div>
            <div style={styles.banner}>
              <h1 style={{ margin: 0, fontSize: '24px', fontWeight: 'bold' }}>Welcome back, {studentName}! 🎓</h1>
              <p style={{ margin: '6px 0 0 0', fontSize: '14px', color: '#e2e8f0', opacity: 0.9 }}>Access your personalized classroom workflows, live timetables, and learning modules.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '18px', marginBottom: '24px' }}>
              {[
                { label: 'Assigned Grade', val: studentGrade, color: '#8b5cf6', textCol: '#6d28d9' },
                { label: 'Enrolled Courses', val: `${studentSubjects.length} Subjects`, color: '#f59e0b', textCol: '#d97706' },
                { label: 'Study Materials', val: `${materialsCount} Items`, color: '#145c2e', textCol: '#145c2e' },
                { label: 'Available Exams', val: `${quizzesCount} Quizzes`, color: '#3b82f6', textCol: '#1d4ed8' }
              ].map((card, i) => (
                <div key={i} style={{ ...styles.statCard, borderLeft: `5px solid ${card.color}` }}>
                  <p style={styles.statLabel}>{card.label}</p>
                  <h3 style={{ margin: '4px 0 0 0', fontSize: '20px', fontWeight: 'bold', color: card.textCol }}>{card.val}</h3>
                </div>
              ))}
            </div>

            <div style={styles.whiteBox}>
              <p style={{ margin: '0 0 12px 0', fontSize: '14px', fontWeight: 'bold', color: '#145c2e' }}>
                📌 Select Course Subject to View Specific Materials & Activities:
              </p>
              <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                {studentSubjects.map((sub, idx) => (
                  <button key={idx} onClick={() => handleSubjectClick(sub)} style={styles.pillBtn}>
                    📖 {sub} (Go to Subject)
                  </button>
                ))}
              </div>
            </div>

            <div style={{ ...styles.whiteBox, marginTop: '24px' }}>
              <h3 style={{ margin: '0 0 18px 0', fontSize: '16px', color: '#1e293b', fontWeight: 'bold' }}>🗓️ Live Weekly Class Timetable ({studentGrade})</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '13.5px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: '#64748b' }}>Time Slot</th>
                    {daysOfWeek.map(day => <th key={day} style={{ padding: '12px', color: '#64748b' }}>{day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {timeSlots.map(slot => (
                    <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '14px 10px', fontWeight: 'bold', textAlign: 'left', color: '#334155' }}>{slot}</td>
                      {daysOfWeek.map(day => {
                        const match = timetable.find(t => (t.day || '').toLowerCase().startsWith(day.toLowerCase()) && (t.time_slot || '').replace(/\s/g, '').toLowerCase() === slot.replace(/\s/g, '').toLowerCase());
                        return (
                          <td key={day} style={{ padding: '6px' }}>
                            {match ? (
                              <div style={styles.classBadge}>
                                <div style={{ fontWeight: 'bold' }}>{match.subject}</div>
                                <div style={{ fontSize: '11px', color: '#15803d' }}>👨‍🏫 {match.teacher}</div>
                              </div>
                            ) : <span style={{ color: '#cbd5e1' }}>-</span>}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      case 'Study Materials':
        return <StudentMaterials user={{ ...user, name: studentName }} selectedSubject={selectedSubject} setSelectedSubject={setSelectedSubject} />;
      case 'Lesson Activities':
        return <StudentActivities user={{ ...user, name: studentName }} selectedSubject={selectedSubject} setSelectedSubject={setSelectedSubject} />;
      case 'Exams & Quizzes':
        return <StudentExams user={{ ...user, name: studentName }} />;
      case 'Class Timetable':
        return <StudentTimetable user={{ ...user, name: studentName }} />;
      case 'Feedback':
        return <Studentfeedback user={{ ...user, name: studentName }} />;
      case 'Settings':
        return <StudentProfileSettings user={{ ...user, name: studentName }} />;
      default:
        return null;
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* Top Header */}
      <header style={styles.header}>
        <img src={logo} alt="Logo" style={{ height: '58px', width: 'auto' }} /> 
        <div style={styles.welcomeText}>
          Welcome, {studentName} 🎓
        </div>
      </header>

      {/* Main Layout Splitter */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        <Sidebar 
          currentSubPage={activeTab} 
          setCurrentSubPage={setActiveTab} 
          onLogoutClick={onLogout} 
          role="student"
        />
        <div style={styles.mainContent}>
          {renderContent()}
        </div>
      </div>

    </div>
  );
}

const styles = {
  header: {
    height: '80px',
    backgroundColor: '#ffffff',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '0 30px',
    borderBottom: '1px solid #e2e8f0',
    zIndex: 10,
    boxShadow: '0 2px 8px rgba(0,0,0,0.03)'
  },
  welcomeText: {
    fontSize: '18px',
    fontWeight: '700',
    color: '#1e293b'
  },
  mainContent: { flex: 1, padding: '28px', overflowY: 'auto', height: '100%', boxSizing: 'border-box' },
  banner: { backgroundColor: '#145c2e', borderRadius: '16px', padding: '24px 30px', color: 'white', marginBottom: '24px', boxShadow: '0 10px 20px -5px rgba(20, 92, 46, 0.25)' },
  whiteBox: { backgroundColor: '#fff', padding: '24px', borderRadius: '18px', border: '1px solid #e2e8f0', boxShadow: '0 4px 14px rgba(0,0,0,0.03)' },
  statCard: { backgroundColor: '#fff', padding: '18px', borderRadius: '14px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' },
  statLabel: { margin: 0, fontSize: '12px', color: '#64748b', fontWeight: 'bold' },
  pillBtn: { padding: '8px 18px', borderRadius: '20px', fontSize: '13px', fontWeight: 'bold', cursor: 'pointer', backgroundColor: '#f0fdf4', color: '#145c2e', border: 'none', transition: 'all 0.2s' },
  classBadge: { backgroundColor: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '8px', padding: '6px', fontSize: '11.5px', color: '#145c2e' }
};
